  color: var(--bara-color-text-muted);
}

.bara-sug__group { display: flex; flex-direction: column; gap: var(--bara-space-2); }
.bara-sug__label {
  font-size: var(--bara-font-size-xs);
  color: var(--bara-color-text-subtle);
}

.bara-sug__items {
  display: flex;
