              </NTag>
            </NSpace>
          </template>

          <p v-for="b in e.body" :key="b.label" class="bara-sec__body">{{ b.text }}</p>

          <dl v-if="e.rest.length" class="bara-sec__rest">
            <div v-for="r in e.rest" :key="r.label" class="bara-sec__field">
              <dt>{{ r.label }}</dt>
              <dd>{{ r.text }}</dd>
            </div>
          </dl>
        </NThing>
      </div>
    </section>
  </div>
</template>

