.bara-res__top {
  display: flex;
  align-items: center;
  gap: var(--bara-space-2);
}
.bara-res__name {
  font-size: var(--bara-font-size-sm);
  color: var(--bara-color-text);
  min-width: 0;
  word-break: break-word;
}
.bara-res__num {
  margin-left: auto;
  flex: none;
  font-family: var(--bara-font-family-mono);
  font-size: var(--bara-font-size-sm);
  color: var(--bara-color-text-muted);
}
</style>
