          class="bara-lic__link"
          :href="r.noticeUrl"
          target="_blank"
          rel="noopener noreferrer"
          translate="no"
        >{{ r.noticeUrl }}</a>

        \x3c!--
          全文按需展开，但**必须随产物分发**：BRP OGL §3 的 affix
