        --\x3e
        <NButton v-if="r.licenseText" size="tiny" quaternary @click="toggle(r.id)">
          {{ t(openLicenses.has(r.id) ? 'about.license.hide' : 'about.license.show', lang) }}
        </NButton>
      </div>

      <pre
        v-if="r.licenseText && openLicenses.has(r.id)"
