      >
        <template #icon><NIcon :component="ICONS.settings" /></template>
      </NButton>
      \x3c!-- 展开/收起：这是「多个部位可展开」中的一处，另一处在坞上 --\x3e
      <NButton
        size="small"
        quaternary
        :title="t(ui.expanded ? 'shell.collapse' : 'shell.expand', ui.lang)"
